def solve(grid, start, goal):
    from collections import deque

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = {}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and not visited[r][c]

    def backtrack(r, c):
        if r == start[0] and c == start[1]:
            path[(r, c)] = None
            return True
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) in path:
                path[(r, c)] = (nr, nc)
                if backtrack(nr, nc):
                    return True
        return False

    if not is_valid(*start) or not is_valid(*goal):
        return []

    queue = deque()
    queue.append(start)
    visited[start[0]][start[1]] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                visited[nr][nc] = True
                queue.append((nr, nc))
                path[(nr, nc)] = (r, c)

    if not backtrack(goal[0], goal[1]):
        return []

    result = []
    current = goal
    while current:
        result.append(current)
        current = path.get(current)
    return result[::-1]
